create procedure [dbo].[ETL_Fact_ProductTransaction]
(
	@Type nvarchar(4000) = null
	,@ParamList nvarchar(4000) = null	
	,@ParentEventID int = null
)
as
--
-- Standardvariabler
--
declare @ProcName sysname, @TranCount int, @EventIDStack varbinary(max)
set @ProcName = app.GetObjectFullName(@@procid)
set @TranCount = @@trancount


begin try
	--------------------------------------------------------------------------
	-- Start
	--------------------------------------------------------------------------
	exec app.LogEventStart @ParentEventID = @ParentEventID, @EventIDStack = @EventIDStack output, @EventObject = @ProcName
			,@EventTitle = 'ETL Fact: ETL_Fact_ProductTransaction'
			,@Description = ''

	 
	
	--------------------------------------------------------------------------
	-- Ladda faktatabell för produkttransaktioner
	--------------------------------------------------------------------------		
	TRUNCATE TABLE [dw].[fact_ProductTransaction]
	INSERT INTO [dw].[fact_ProductTransaction]
	(
		[TransactionDateID]
		,[InvoiceDateID]
	
		,[LagerID] 
		,[LeverantörID] 
		,[TransaktionstypID] 
		,[AnläggningID] 
		,[KundID] 
		,[FakturerasKundID] 
		,[SäljInköpAnställdID] 
		,[AnställdID] 
		,[KampanjID] 
		,[VarugruppID] 
		,[KassaID] 
		,[ProjektID] 
		,[AvdelningID] 
		,[ProduktID] 
		,[FakturaBelopp]
		,[FakturaAntal]
		,[FakturaRabatt]
		,[FakturaKostnad]
		,[FakturaVolym]
		,[FakturaEmballagevikt]
		,[FakturaNettovikt]
		,[InvoiceNumber]
		,[JNo]
		,[TrNo]
		,[OrdNo]
		,[OrdLnNo]
		,[ChDt]
		,[ChTm]
		,[Txt]
		,[RowTypeID]
		,[SA_SourceSystemID]
	)
	select
		[TransactionDateID] = f.TrDt
		,[InvoiceDateID] = f.InvoDt
		
		,[LagerID] = isnull([Lager].[LagerID], -4)
		,[LeverantörID] = isnull([Leverantör].[LeverantörID], -5)
		,[TransaktionstypID] = isnull([Transaktionstyp].[TransaktionstypID], -6)
		,[AnläggningID] = isnull([Anläggning].[AnläggningID], -7)
		,[KundID] = isnull([Kund].[KundID], -19)
		,[FakturerasKundID] = isnull([Faktureras_Kund].[KundID], -19)
		,[SäljInköpAnställdID] = isnull([Sälj_Inköp_Anställd].[AnställdID], -10)
		,[AnställdID] = isnull([Anställd].[AnställdID], -10)
		,[KampanjID] = isnull([Kampanj].[KampanjID], -12)
		,[VarugruppID] = isnull([Varugrupp].[VarugruppID], -13)
		,[KassaID] = isnull([Kassa].[KassaID], -14)
		,[ProjektID] = isnull([Projekt].[ProjektID], -15)
		,[AvdelningID] = isnull([Avdelning].[AvdelningID], -16)
		,[ProduktID] = isnull([Produkt].[ProduktID], -18)
		
	
		,[FakturaBelopp] = f.DAm
		,[FakturaAntal] = f.NoInvoAb
		,[FakturaRabatt] = f.DDstDc
		,[FakturaKostnad] = f.IncCst
		,[FakturaVolym] = f.VolL
		,[FakturaEmballagevikt] = f.TareL
		,[FakturaNettovikt] = f.NWgtL
		,[InvoiceNumber] = f.InvoNo
		,[JNo] = f.JNo
		,[TrNo] = f.TrNo
		,[OrdNo] = f.OrdNo
		,[OrdLnNo] = f.OrdLnNo
		,[ChDt] = f.ChDt
		,[ChTm] = f.ChTm
		,[Txt] = f.Descr
		,[RowTypeID] = 0
		,[SA_SourceSystemID] = f.SA_SourceSystemID				
	from
		[INSIKT_KUND_SA].visma.ProdTr f	
			left join [dw].[base_Lager] [Lager] on
				[Lager].Code = f.[FrStc]	
			left join [dw].[base_Leverantör] [Leverantör] on
				[Leverantör].Code = f.[SupNo]	
			left join [dw].[base_Transaktionstyp] [Transaktionstyp] on
				[Transaktionstyp].Code = f.[TrTp]	
			left join [dw].[base_Anläggning] [Anläggning] on
				[Anläggning].Code = f.[PropNo]	
			left join [dw].[base_Kund] [Kund] on
				[Kund].Code = f.[CustNo]	
			left join [dw].[base_Kund] [Faktureras_Kund] on
				[Faktureras_Kund].Code = f.[InvoCust]	
			left join [dw].[base_Anställd] [Sälj_Inköp_Anställd] on
				[Sälj_Inköp_Anställd].Code = f.[SelBuy]	
			left join [dw].[base_Anställd] [Anställd] on
				[Anställd].Code = f.[EmpNo]	
			left join [dw].[base_Kampanj] [Kampanj] on
				[Kampanj].Code = f.[R6]	
			left join [dw].[base_Varugrupp] [Varugrupp] on
				[Varugrupp].Code = f.[R4]	
			left join [dw].[base_Kassa] [Kassa] on
				[Kassa].Code = f.[R3]	
			left join [dw].[base_Projekt] [Projekt] on
				[Projekt].Code = f.[R2]	
			left join [dw].[base_Avdelning] [Avdelning] on
				[Avdelning].Code = f.[R1]	
			left join [dw].[base_Produkt] [Produkt] on
				[Produkt].Code = f.[ProdNo]	
	where
		f.StrSt = 0 -- Excludera kits ingående detaljrader.
		and (f.TransSt & 16 = 0)
	
	--------------------------------------------------------------------------

	exec app.LogEventStop @EventIDStack = @EventIDStack out
	--------------------------------------------------------------------------
	-- Stop
	--------------------------------------------------------------------------
end try
begin catch	
	--
	-- Roll back any transactions and log errors
	--
	if @TranCount = 0 and @@trancount > 0 rollback tran
	exec app.HandleProcError @EventIDStack out, @ParentEventID, @ProcName
	exec app.ReThrowError
end catch

GO
